#!/bin/bash
# Build the AI-2 packages (unsigned) inside the ai2-artix-build container.
#
#   docker exec ai2-iso-build bash /ai2-repo/www/ai-2/packaging/build-packages.sh [pkg...]
#
# pkg is any of: ai2-keyring ai-2 ai2-llama-cpp ai2-whisper-cpp ai-2-gopher, or a Knowledge Pack package
# (ai2-help ai2-everyday ai2-linux-essentials, generated by
# tools/render-pack-packages.py from the catalog). Default: the first three.
# Output: /ai2-repo/www/ai-2/packaging/candidate/*.pkg.tar.zst (gitignored), see OUT below.
# Signing is deliberately NOT done here; the key lives on the laptop, see
# sign-and-publish.sh.
set -euo pipefail

REPO=/ai2-repo
PKG_SRC=$REPO/www/ai-2/packaging
# Builds land in candidate/, NOT out/. sign-and-publish.sh signs whatever is in
# out/, and a package built and then thought better of was published that way
# (0.18.2, 2026-09-17). A candidate is first tried on real hardware with an
# unsigned `pacman -U`; only one that passed is moved to out/ by hand.
OUT=$PKG_SRC/candidate
WORK=/home/builder/pkgbuild
# Persistent source cache: the llama.cpp bare clone is ~2 GB, keep it across runs.
SRCDEST=/home/builder/srcdest
export MAKEFLAGS="-j$(nproc)"

pkgs=("$@")
[ ${#pkgs[@]} -eq 0 ] && pkgs=(ai2-keyring ai-2 ai2-llama-cpp)
# The pack packages carry the file the catalog publishes, so they are written
# from the catalog rather than edited; refuse to build a stale one.
for p in "${pkgs[@]}"; do
  case "$p" in
    ai2-help|ai2-everyday|ai2-linux-essentials)
      python3 "$REPO/www/ai-2/tools/render-pack-packages.py" --check || exit 1
      break;;
  esac
done

if [ "$(id -u)" -eq 0 ]; then
  # makepkg refuses root; re-exec as builder (created in the image).
  exec sudo -u builder -E MAKEFLAGS="$MAKEFLAGS" bash "$0" "${pkgs[@]}"
fi

mkdir -p "$OUT" "$WORK" "$SRCDEST"

# The ai-2 tool tarball comes from git, so a package always maps to a commit.
# The repo is mounted read-only in spirit: git archive reads HEAD, and a dirty
# tree is refused unless AI2_ALLOW_DIRTY=1.
make_ai2_tarball() {
  local ver
  ver=$(sed -n 's/^__version__ = "\(.*\)"/\1/p' "$REPO/www/ai-2/ai2/__init__.py")
  [ -n "$ver" ] || { echo "cannot read __version__" >&2; exit 1; }
  if [ -n "$(git -C "$REPO" status --porcelain -- www/ai-2 ':!www/ai-2/packaging/out')" ] \
     && [ "${AI2_ALLOW_DIRTY:-0}" != 1 ]; then
    echo "www/ai-2 has uncommitted changes; commit them or set AI2_ALLOW_DIRTY=1" >&2
    exit 1
  fi
  git -C "$REPO" archive --format=tar.gz --prefix="ai-2-$ver/" -o "$WORK/ai-2/ai-2-$ver.tar.gz" HEAD:www/ai-2
  echo "ai-2 tarball at $WORK/ai-2/ai-2-$ver.tar.gz (HEAD $(git -C "$REPO" rev-parse --short HEAD))"
  # keep the PKGBUILD's pkgver honest
  sed -i "s/^pkgver=.*/pkgver=$ver/" "$WORK/ai-2/PKGBUILD"
}

# The ai-2 package carries the pack catalog and the image carries the pack
# files; a release where the two disagree, or where the copy is behind the
# catalog, ships packs that cannot be installed by name. Checked before the
# build, not after somebody notices.
if printf '%s\n' "${pkgs[@]}" | grep -qx ai-2; then
  python3 "$REPO/www/ai-2/tools/sync-pack-catalog.py" --check
  rc=$?
  [ "$rc" = 1 ] && { echo "refusing to build ai-2 with a stale pack catalog"; exit 1; }
  # The signatures the chat reads (ai2/data/signatures/) are made from the pack
  # files and pinned to the hashes in the catalog. No network, no pack file.
  python3 "$REPO/www/ai-2/tools/build-pack-signatures.py" --check \
    || { echo "refusing to build ai-2 with stale Knowledge Pack signatures"; exit 1; }
fi

# The compiler the two engine packages are built with, pinned so a later build
# reproduces the gated one (ai2-llama-cpp 12359-1 and ai2-whisper-cpp 1.9.6-1
# were built with these files). The container's package lists named 23.1.4
# when the mirrors no longer had it, so the files come from the Artix archive,
# checked by SHA-256, at the version of the llvm-libs the container already
# had (no partial upgrade). A different version installed is refused, never
# swapped silently: moving the compiler is a decision with its own gates.
TOOLCHAIN_VER=23.1.4-1
TOOLCHAIN=(
  "llvm-libs 9978934f7493532cb265ba8f7b8723dcdb28baf88e8685743943a37dbc8f156d"
  "clang-libs bdbe758b52f02f731c80473959a4272f813b5decd96830ca290aa804df54ed8f"
  "llvm-lit 284107041540bd66acac60cdb4a28183e3bcbfd4183fe3d3ff28c98755e7ed15"
  "llvm ea97d38d05d0f0d06cb054dd5363401d1da22cac771d969a4a819444d3f03302"
  "compiler-rt 25ad65aee1c924945a68410c5a6099cb24bdbca5452ff8ac5ca4eba6c3fe83a1"
  "clang 3feaa9486a5fd094c649192187ec988f48f5ff621542608e1ad35718462ebf1c"
)
ensure_toolchain() {
  local entry name sum have f need=()
  for entry in "${TOOLCHAIN[@]}"; do
    read -r name sum <<<"$entry"
    have=$(pacman -Q "$name" 2>/dev/null | awk '{print $2}' || true)
    [ "$have" = "$TOOLCHAIN_VER" ] && continue
    if [ -n "$have" ]; then
      echo "refusing to build: $name $have is installed, the engines are built with $TOOLCHAIN_VER" >&2
      exit 1
    fi
    f=$name-$TOOLCHAIN_VER-x86_64.pkg.tar.zst
    curl -fsSL -o "$WORK/$f" "https://archive.artixlinux.org/packages/${name:0:1}/$name/$f"
    echo "$sum  $WORK/$f" | sha256sum -c --quiet || { echo "checksum mismatch: $f" >&2; exit 1; }
    need+=("$WORK/$f")
  done
  [ ${#need[@]} -eq 0 ] || sudo pacman -U --asdeps --noconfirm "${need[@]}"
  clang --version | head -1
}
if printf '%s\n' "${pkgs[@]}" | grep -qx -e ai2-llama-cpp -e ai2-whisper-cpp; then
  ensure_toolchain
fi

for p in "${pkgs[@]}"; do
  echo "=================== $p ==================="
  rm -rf "$WORK/$p"
  cp -a "$PKG_SRC/$p" "$WORK/$p"
  cd "$WORK/$p"
  [ "$p" = ai-2 ] && make_ai2_tarball
  # -s installs makedepends via sudo pacman; -f overwrites a stale package;
  # -C cleans an old srcdir so a changed source is never reused by accident.
  # A pack package only unpacks a downloaded file, and its one dependency
  # (ai-2) is a runtime relation that the build container has no reason to
  # have installed, so -s would stop on "target not found".
  deps=(-s)
  case "$p" in ai2-help|ai2-everyday|ai2-linux-essentials) deps=(--nodeps);; esac
  # ai-2 needs its own dependencies for check(), but not the app or the browser,
  # which its tests never start and which may not be in [ai2] yet when both go out together,
  # nor udisks2 and gvfs, which the tests never use and whose cryptsetup needs a newer
  # openssl than the container has (2026-11-18), nor python-gobject and poppler, which the tests
  # never load and which the container's package lists could no longer fetch (2026-11-26).
  if [ "$p" = ai-2 ]; then
    # Only what is missing, as -s does: installing one newer package over old
    # package lists is a partial upgrade (python without its expat, 2026-11-04).
    # pacman -T exits 127 when it lists something, which is not a failure here.
    ( . ./PKGBUILD; pacman -T "${depends[@]}" "${checkdepends[@]}" || true ) \
      | sed '/^ai-2-gopher/d; /^firefox-esr/d; /^udisks2/d; /^gvfs/d; /^python-gobject/d; /^poppler/d' | xargs -r sudo pacman -S --noconfirm
    deps=(--nodeps)
  fi
  PKGDEST="$OUT" SRCDEST="$SRCDEST" makepkg "${deps[@]}" -f -C --noconfirm
  echo "--- namcap ---"
  namcap PKGBUILD || true
  for f in "$OUT/$p"*.pkg.tar.zst; do namcap "$f" || true; done
done

echo
echo "Built packages in $OUT:"
ls -la "$OUT"/*.pkg.tar.zst
